        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         yy,xx=y+dy,x+dx
         if 0<=yy<h and 0<=xx<w and grid[yy][xx]==1 and (yy,xx) not in seen: seen.add((yy,xx)); st.append((yy,xx))
       comps.append(q)
    for comp in comps:
      r0=min(r for r,c in comp); r1=max(r for r,c in comp); c0=min(c for r,c in comp); c1=max(c for r,c in comp)
